{
  "conversations": [
    {
      "title": "Accept or decline a dance",
      "lines": [
        { "speaker": "partner", "text": "Wanna dance?" },
        { "speaker": "you", "text": "I'd love to." },
        { "speaker": "you", "text": "I'm taking a break right now.", "or": true },
        { "speaker": "partner", "text": "No worries." },
        { "speaker": "partner", "text": "Maybe later?", "or": true }
      ]
    },
    {
      "title": "Compliment someone's dancing",
      "lines": [
        { "speaker": "you", "text": "You're a great dancer." },
        { "speaker": "partner", "text": "Thanks!" },
        { "speaker": "you", "text": "I love your spins." },
        { "speaker": "partner", "text": "Appreciate it." },
        { "speaker": "partner", "text": "You're doing great too.", "or": true }
      ]
    },
    {
      "title": "Chat between songs",
      "lines": [
        { "speaker": "partner", "text": "Come here often?" },
        { "speaker": "you", "text": "It's my first time here." },
        { "speaker": "you", "text": "I come every week.", "or": true },
        { "speaker": "partner", "text": "How do you like it?" },
        { "speaker": "you", "text": "I'm having a blast." },
        { "speaker": "partner", "text": "Me too." }
      ]
    }
  ]
}
